async function executeGraphql(db2, source, variables = {}, { curatorRuntime: curatorRuntime2 } = {}) {
  return graphql({ schema: schema2, source, rootValue: resolvers(db2, { curatorRuntime: curatorRuntime2 }), variableValues: variables });
}

// src/indexer.ts
init_db();
init_err_radio();
init_plugins();
function startIndexer({
  databasePath: databasePath2,
  curatorRuntime: curatorRuntime2,
  intervalMs = 6e4,
  logger: logger2 = console,
  runImmediate = true
}) {
  const db2 = openDatabase(databasePath2);
  const plugin = createErrRadioPlugin(db2);
  let running = false;
  const runActiveAgents = async () => {
    if (running) return;
    running = true;
    try {
      const engine2 = await registerKeerisPlugins({ db: db2 });
      const activeAgents = engine2.getActiveAgents();
      for (const { name, definition: agent } of activeAgents) {
        logger2.log(`[AgentScheduler] Running scheduled agent: ${name}`);
        if (curatorRuntime2 && typeof curatorRuntime2.triggerAgent === "function") {
          await curatorRuntime2.triggerAgent(name, agent.args || {});
          logger2.log(`[AgentScheduler] Created Request task for agent ${name} in Curator database.`);
        } else {
          const toolName = agent.toolName || "keeris_scrape";
          const tool = plugin.tools[toolName];
          if (tool) {
            const res = await tool.runAsync({ args: agent.args || {} });
            logger2.log(`[AgentScheduler] Agent ${name} completed: ${res?.episodesParsed ?? 0} parsed, ${res?.tracksSaved ?? 0} tracks saved`);
          }
        }
      }
    } catch (error) {
      logger2.error(`[AgentScheduler] Agent run failed: ${error?.message}`);
    } finally {
      running = false;
    }
  };
  if (runImmediate) {
    runActiveAgents();
  }
  const timer = curatorRuntime2 ? null : setInterval(runActiveAgents, intervalMs);
  return {
    db: db2,
    run: runActiveAgents,
    stop: () => {
      if (timer) clearInterval(timer);
      db2.close();
    }
  };
}

// src/server/index.ts
init_curator_runtime();
var currentDir = dirname2(fileURLToPath6(import.meta.url));
